SELECT DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, ROUND(AVG(cost), 2) AS avg_cost, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, ROUND(AVG(cost), 2) AS avg_cost_2, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, COUNT(CASE WHEN carrier = 'Flash' THEN 1 END) AS flash_count, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN carrier = 'UPS' THEN 1 END), 0), 2) AS cost_per_ups FROM shipments GROUP BY CUBE (DATE_TRUNC('QUARTER', shipped_date));
